/** CSS custom-property name for a token path. */
export function tokenVar(path: TokenPath): string {
  return 'var(--nhis-' + path.split('.').map((s) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()).join('-') + ')';
}
